    private void jButtonAdelanteActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButtonAdelanteActionPerformed
        // TODO add your handling code here:
        if (!control.esVacia()) {
            control.avanzar();
            actualizarInformacion();
            if (control.esUltimo()) {
                jButtonAdelante.setVisible(false);
            }else if(!control.esPrimero()){
                jButtonAtras.setVisible(true);
            } 
        }
    }//GEN-LAST:event_jButtonAdelanteActionPerformed

    private void jButtonUltimoActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButtonUltimoActionPerformed
        // TODO add your handling code here:
        if (!control.esPrimero()&&!control.esUltimo()) {
            control.irUltimo();
            actualizarInformacion();
            jButtonAtras.setVisible(true);
            jButtonAdelante.setVisible(false);
        }
        
    }//GEN-LAST:event_jButtonUltimoActionPerformed

    private void jButtonAtrasActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButtonAtrasActionPerformed
        // TODO add your handling code here:
        if (!control.esVacia()) {
            control.retroceder();
            actualizarInformacion();
            if (control.esPrimero()) {
                jButtonAtras.setVisible(false);
            }else if(!control.esUltimo()){
                jButtonAdelante.setVisible(true);
            }
        }
    }//GEN-LAST:event_jButtonAtrasActionPerformed

    private void jButtonPrimeroActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButtonPrimeroActionPerformed
        // TODO add your handling code here:
        if (!control.esPrimero()&&!control.esUltimo()) {
            control.irPrimero();
            actualizarInformacion();
            jButtonAdelante.setVisible(true);
            jButtonAtras.setVisible(false);
        }
    }//GEN-LAST:event_jButtonPrimeroActionPerformed

    private void jButtonBorrarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButtonBorrarActionPerformed
        // TODO add your handling code here:
        if (!control.esVacia()) {
            if (control.esPrimero()&&!control.esUltimo()) {
            control.borrarCliente();
            actualizarInformacion();
            }
            else if(control.esPrimero()&&control.esUltimo()) {
                jButtonAdelante.setVisible(false);
                jButtonAtras.setVisible(false);
            }
            else {
                
                control.borrarCliente();
                control.retroceder();
                actualizarInformacion();
            }
        }
    }//GEN-LAST:event_jButtonBorrarActionPerformed

    private void actualizarInformacion(){
        Cliente actual = control.obtenerClienteActual();
        nombreField.setText(actual.getNombre());
        puntosField.setText(actual.getPuntos());
        numeroField.setText(actual.getNumero()+"");
        fechaField.setText(actual.getFecha().toString());
    }
